CREATE TABLE `players` (`player_id` DECIMAL(18,2), `first_name` VARCHAR(100), `last_name` VARCHAR(100), `hand` VARCHAR(100), `birth_date` DATETIME, `country_code` VARCHAR(100));
CREATE TABLE `matches` (`best_of` DECIMAL(18,2), `draw_size` DECIMAL(18,2), `loser_age` DECIMAL(18,2), `loser_entry` VARCHAR(100), `loser_hand` VARCHAR(100), `loser_ht` DECIMAL(18,2), `loser_id` DECIMAL(18,2), `loser_ioc` VARCHAR(100), `loser_name` VARCHAR(100), `loser_rank` DECIMAL(18,2), `loser_rank_points` DECIMAL(18,2), `loser_seed` DECIMAL(18,2), `match_num` DECIMAL(18,2), `minutes` DECIMAL(18,2), `round` VARCHAR(100), `score` VARCHAR(100), `surface` VARCHAR(100), `tourney_date` DATETIME, `tourney_id` VARCHAR(100), `tourney_level` VARCHAR(100), `tourney_name` VARCHAR(100), `winner_age` DECIMAL(18,2), `winner_entry` VARCHAR(100), `winner_hand` VARCHAR(100), `winner_ht` DECIMAL(18,2), `winner_id` DECIMAL(18,2), `winner_ioc` VARCHAR(100), `winner_name` VARCHAR(100), `winner_rank` DECIMAL(18,2), `winner_rank_points` DECIMAL(18,2), `winner_seed` DECIMAL(18,2), `year` DECIMAL(18,2));
CREATE TABLE `rankings` (`ranking_date` DATETIME, `ranking` DECIMAL(18,2), `player_id` DECIMAL(18,2), `ranking_points` DECIMAL(18,2), `tours` DECIMAL(18,2));
